const fs = require('fs');

const data = fs.readFileSync(0, 'utf8');
let idx = 0;
const len = data.length;

function nextInt() {
  while (idx < len && data.charCodeAt(idx) <= 32) idx++;
  let num = 0;
  while (idx < len && data.charCodeAt(idx) > 32) {
    num = num * 10 + (data.charCodeAt(idx) - 48);
    idx++;
  }
  return num;
}

const S = nextInt();
const T = nextInt();

const adj = Array.from({ length: S + 1 }, () => new Uint8Array(S + 1));

for (let i = 0; i < T; i++) {
  const x = nextInt();
  const y = nextInt();
  adj[x][y] = 1;
  adj[y][x] = 1;
}

const P = nextInt();
let answer = 0;

for (let i = 0; i < P; i++) {
  const N = nextInt();
  let prev = nextInt();
  let ok = true;

  for (let j = 1; j < N; j++) {
    const cur = nextInt();
    if (ok && adj[prev][cur] === 0) {
      ok = false;
    }
    prev = cur;
  }

  if (ok) answer++;
}

console.log(answer);
